#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
# openvela AI Contest - DeepSeek Harness (dsh) backfill adapter.
#
# Reads dsh session logs from $DSH_HOME/sessions (default ~/.dsh/sessions).
# Layout: sessions/<encoded-project-dir>/<session-id>/session.v4.jsonl[.zstd]
# One zstd frame per append batch; the header is its own frame, so a log
# that is still being written always yields at least the header.
#
# Format (session format v4, verified against dsh 0.2.0-rc.2 2026-11-03,
# 49 sessions / 44k events):
#   line 1            {type:"session", version, id, createdAt, cwd, ...}
#   every later line  {type, seq, time(ms epoch), data}
# Event vocabulary (KNOWN_SESSION_EVENT_TYPES) is large; the contest
# schema only needs four roles, so mapping is:
#   user/message      role=user      only when data.source.kind=="user"
#   assistant/message role=assistant text + reasoning + usage
#   tool/call         role=tool      name/arguments/callId
#   tool/result       role=tool      "<result>" + output, paired by callId
# Everything else is harness machinery (request/header carries the tool
# schemas, system/message the system prompt, agent/inbox/spliced the
# inbox delivery that user/message mirrors, compaction/* bookkeeping,
# stream[] token chunks) and is skipped.

from __future__ import annotations

import hashlib
import json
import os
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

TOOL_ID = "dsh"
SCHEMA_VERSION = "1.0"
SESSION_FORMAT_VERSION = 4
COLLECTION_MODE = "backfill-local-log"

# Bulk fields inside tool/result meta that duplicate the tool output or
# carry full file bodies; only their paths are kept.
META_BULK_KEYS = ("lines", "diffs", "files", "sources", "oldText", "newText")

USER_SOURCE_KIND = "user"


def dsh_home() -> Path:
    override = os.environ.get("DSH_HOME_BACKFILL_OVERRIDE")
    if override:
        return Path(override)
    env = os.environ.get("DSH_HOME")
    if env and env.strip():
        return Path(env)
    return Path.home() / ".dsh"


def _ms_to_iso(ms: Any) -> str:
    if isinstance(ms, (int, float)):
        return datetime.fromtimestamp(ms / 1000.0, tz=timezone.utc).isoformat()
    return datetime.now(timezone.utc).isoformat()


def _sha256_file(path: Path) -> str | None:
    if not path.is_file():
        return None
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def _zstd_bytes(path: Path) -> bytes:
    """Decode a multi-frame zstd session log.

    Tries the `zstandard` module, then the `zstd` CLI. A torn final frame
    (session still being written) is expected: the CLI exits 1 after
    emitting every complete frame, which is exactly what we keep.
    """
    data = path.read_bytes()
    try:
        import zstandard  # type: ignore
        dctx = zstandard.ZstdDecompressor()
        return dctx.decompressobj().decompress(data)
    except ImportError:
        pass
    except Exception as e:  # noqa: BLE001 - fall through to CLI
        sys.stderr.write(f"[dsh] zstandard module failed on {path.name}: {e}\n")
    try:
        proc = subprocess.run(["zstd", "-dc", str(path)],
                              capture_output=True)
        if proc.returncode in (0, 1) and proc.stdout:
            return proc.stdout
        sys.stderr.write(f"[dsh] zstd failed on {path.name}: "
                         f"{proc.stderr.decode('utf-8', 'replace')[:200]}\n")
    except FileNotFoundError:
        sys.stderr.write(
            "[dsh] cannot decompress session logs: install the `zstd` CLI "
            "(or `pip install zstandard`)\n")
    return b""


def read_session_log(path: Path) -> list[dict[str, Any]] | None:
    raw = _zstd_bytes(path) if path.suffix == ".zstd" else path.read_bytes()
    if not raw:
        return None
    records: list[dict[str, Any]] = []
    for line in raw.decode("utf-8", "replace").splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            rec = json.loads(line)
        except json.JSONDecodeError:
            # torn tail of a live log: everything parsed so far is complete
            break
        if isinstance(rec, dict):
            records.append(rec)
    return records


def _blocks_text(content: Any, block_type: str) -> str:
    if not isinstance(content, list):
        return ""
    parts = []
    for block in content:
        if not isinstance(block, dict) or block.get("type") != block_type:
            continue
        text = block.get("text")
        if isinstance(text, str) and text.strip():
            parts.append(text)
    return "\n".join(parts)


def _count_blocks(content: Any, block_type: str) -> int:
    if not isinstance(content, list):
        return 0
    return sum(1 for b in content
               if isinstance(b, dict) and b.get("type") == block_type)


def _parse_arguments(raw: Any) -> Any:
    if isinstance(raw, str):
        try:
            return json.loads(raw)
        except json.JSONDecodeError:
            return raw
    return raw


def _meta_paths(meta: Any) -> list[str]:
    if not isinstance(meta, dict):
        return []
    out: list[str] = []

    def add(value: Any) -> None:
        if isinstance(value, str) and value and value not in out:
            out.append(value)

    add(meta.get("path"))
    for key in ("paths",):
        for value in meta.get(key) or []:
            add(value)
    for key in ("files", "diffs"):
        for item in meta.get(key) or []:
            if isinstance(item, dict):
                add(item.get("path"))
    return out


def _meta_summary(meta: Any) -> dict[str, Any] | None:
    """Keep the audit-worthy scalars of a tool/result meta, drop the bulk."""
    if not isinstance(meta, dict):
        return None
    summary: dict[str, Any] = {}
    for key, value in meta.items():
        if key in ("lines", "oldText", "newText"):
            continue
        if key in ("diffs", "files", "paths"):
            summary[key] = _meta_paths({key: value})
        elif key == "sources":
            urls = [s.get("url") for s in value
                    if isinstance(s, dict) and s.get("url")]
            if urls:
                summary["sources"] = urls
        elif isinstance(value, (str, int, float, bool)):
            summary[key] = value
    return summary or None


def session_to_events(records: list[dict[str, Any]]) -> tuple[
        dict[str, Any] | None, list[dict[str, Any]], dict[str, Any]]:
    """Convert one parsed session log into contest events.

    Returns (header, events, stats). Events are in log order, which is
    already time-ordered (0 non-monotonic transitions across the corpus).
    """
    header = records[0] if records else None
    if not header or header.get("type") != "session":
        return None, [], {}
    if header.get("version") != SESSION_FORMAT_VERSION:
        return None, [], {}

    events: list[dict[str, Any]] = []
    stats = {"images_dropped": 0, "unknown_types": 0,
             "tokens_in": 0, "tokens_out": 0, "model": None,
             "title": None}

    for rec in records[1:]:
        etype = rec.get("type")
        data = rec.get("data") or {}
        if not isinstance(data, dict):
            data = {}
        ts = _ms_to_iso(rec.get("time"))

        if etype == "user/message":
            source = data.get("source") or {}
            if source.get("kind") != USER_SOURCE_KIND:
                continue
            content = data.get("content")
            text = _blocks_text(content, "text")
            stats["images_dropped"] += _count_blocks(content, "image")
            if not text:
                continue
            events.append({"ts": ts, "role": "user", "text": text})

        elif etype == "assistant/message":
            message = data.get("message") or {}
            content = message.get("content")
            text = _blocks_text(content, "text")
            thinking = _blocks_text(content, "reasoning")
            stats["images_dropped"] += _count_blocks(content, "image")
            if not text and not thinking:
                continue
            ev: dict[str, Any] = {"ts": ts, "role": "assistant"}
            if text:
                ev["text"] = text
            if thinking:
                ev["thinking"] = thinking
            model = (message.get("source") or {}).get("model")
            if model:
                ev["model"] = model
                stats["model"] = model
            usage = data.get("usage") or {}
            if isinstance(usage.get("inputTokens"), int):
                ev["tokens_in"] = usage["inputTokens"]
                stats["tokens_in"] += usage["inputTokens"]
            if isinstance(usage.get("outputTokens"), int):
                ev["tokens_out"] = usage["outputTokens"]
                stats["tokens_out"] += usage["outputTokens"]
            if data.get("interrupted"):
                ev["metadata"] = {"interrupted": True}
            events.append(ev)

        elif etype == "tool/call":
            events.append({
                "ts": ts,
                "role": "tool",
                "tool_name": data.get("name") or "unknown",
                "tool_call_id": data.get("callId") or "",
                "input": _parse_arguments(data.get("arguments")),
                "output": None,
            })

        elif etype == "tool/result":
            message = data.get("message") or {}
            content = message.get("content")
            stats["images_dropped"] += _count_blocks(content, "image")
            ev = {
                "ts": ts,
                "role": "tool",
                "tool_name": "<result>",
                "tool_call_id": message.get("toolCallId") or
                data.get("toolCallId") or "",
                "input": None,
                "output": _blocks_text(content, "text"),
            }
            if message.get("isError"):
                ev["is_error"] = True
            meta = _meta_summary(data.get("meta"))
            if data.get("error"):
                meta = {**(meta or {}), "error": data["error"]}
            if meta:
                ev["metadata"] = meta
            paths = _meta_paths(data.get("meta"))
            if paths:
                ev["files_touched"] = paths
            events.append(ev)

        elif etype == "session/title":
            title = data.get("title")
            if isinstance(title, str) and title:
                stats["title"] = title

        elif etype in ("session", "turn/start", "turn/end", "step/start",
                       "step/end", "request/header", "request/context",
                       "system/message", "agent/inbox/spliced",
                       "session/title-llm-request", "session/end-seed",
                       "sandbox/mode", "approval/policy", "permission/preset",
                       "compaction/start", "compaction/end",
                       "compaction/prune", "compaction/summary",
                       "assistant/attempt", "todo/write",
                       "deliverables/presented", "workspace/changes",
                       "subagent/catalog", "subagent/descriptor",
                       "session-log-deepseek/delivery-accepted",
                       "web/deepseek-search-llm-request"):
            continue

        else:
            # unknowns are counted, never fatal: a newer dsh may add types
            stats["unknown_types"] += 1

    return header, events, stats


def _find_workspace_root(start: Path) -> Path | None:
    cur = start.resolve()
    for candidate in [cur, *cur.parents]:
        if (candidate / ".repo").is_dir():
            return candidate
    return None


def _write_manifest(dest: Path, github_login: str, team_id: str,
                    session_id: str, events: list[dict], rel_path: str,
                    integrity: dict, stats: dict,
                    header: dict) -> None:
    member_dir = dest / "logs" / github_login
    manifest_path = member_dir / "manifest.json"
    if manifest_path.exists():
        try:
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            manifest = {}
    else:
        manifest = {}
    manifest.setdefault("schema_version", SCHEMA_VERSION)
    manifest["team_id"] = team_id
    manifest["github_login"] = github_login
    manifest.setdefault("generator", f"backfill-{TOOL_ID}@{TOOL_ID}")
    sessions = manifest.setdefault("sessions", [])
    entry = next(
        (s for s in sessions if s.get("session_id") == session_id), None)
    new_entry = {
        "session_id": session_id,
        "tool": TOOL_ID,
        "started_at": events[0]["ts"],
        "last_event_at": events[-1]["ts"],
        "event_count": len(events),
        "file_path": rel_path,
        "collection_mode": COLLECTION_MODE,
        "health": "ok",
        "source_integrity": integrity,
        "tokens_total": stats["tokens_in"] + stats["tokens_out"],
    }
    if stats.get("model"):
        new_entry["model"] = stats["model"]
    if stats.get("title"):
        new_entry["title"] = stats["title"]
    if header.get("parentSession"):
        new_entry["parent_session_id"] = header["parentSession"]
    if header.get("origin"):
        new_entry["origin"] = header["origin"]
    if isinstance(header.get("delegationDepth"), int):
        new_entry["delegation_depth"] = header["delegationDepth"]
    if entry:
        entry.update(new_entry)
    else:
        sessions.append(new_entry)
    manifest["updated_at"] = datetime.now(timezone.utc).isoformat()
    manifest_path.parent.mkdir(parents=True, exist_ok=True)
    manifest_path.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2),
        encoding="utf-8")


def _session_in_manifest(dest: Path, github_login: str,
                         session_id: str) -> bool:
    manifest_path = dest / "logs" / github_login / "manifest.json"
    if not manifest_path.is_file():
        return False
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return False
    return any(
        s.get("session_id") == session_id and s.get("tool") == TOOL_ID
        for s in manifest.get("sessions", []))


def iter_session_logs(home: Path) -> list[Path]:
    root = home / "sessions"
    if not root.is_dir():
        return []
    return sorted(p for p in root.glob("*/*/session.v*.jsonl*") if p.is_file())


def backfill(dest: Path, team_id: str, github_login: str,
             since: str | None = None) -> int:
    home = dsh_home()
    logs = iter_session_logs(home)
    if not logs:
        print(f"[dsh] no session logs under {home}; skipping")
        return 0

    workspace_root = _find_workspace_root(dest)
    if workspace_root is None:
        print("[dsh] destination is not inside an openvela workspace "
              "(no .repo/); skipping")
        return 0
    workspace_root = workspace_root.resolve()

    total = imported = skipped = 0
    for path in logs:
        records = read_session_log(path)
        header, events, stats = session_to_events(records or [])
        if header is None:
            continue
        total += 1

        cwd = header.get("cwd")
        if not cwd:
            continue
        try:
            in_ws = Path(cwd).resolve().is_relative_to(workspace_root)
        except (OSError, ValueError):
            in_ws = False
        if not in_ws:
            continue
        if since and events and events[0]["ts"][:10] < since:
            continue
        sid = header.get("id") or path.parent.name
        if _session_in_manifest(dest, github_login, sid):
            skipped += 1
            continue
        if not events:
            continue

        integrity = {
            "main_sha256": _sha256_file(path),
            "main_size": path.stat().st_size,
            "main_mtime": datetime.fromtimestamp(
                path.stat().st_mtime, tz=timezone.utc).isoformat(),
            "captured_at": datetime.now(timezone.utc).isoformat(),
        }
        date_str = events[0]["ts"][:10]
        rel_path = f"logs/{github_login}/{date_str}/{TOOL_ID}__{sid}.jsonl"
        jsonl_path = dest / rel_path
        jsonl_path.parent.mkdir(parents=True, exist_ok=True)

        with jsonl_path.open("w", encoding="utf-8") as f:
            for seq, e in enumerate(events):
                out = {
                    "schema_version": SCHEMA_VERSION,
                    "session_id": sid,
                    "team_id": team_id,
                    "github_login": github_login,
                    "tool": TOOL_ID,
                    "seq": seq,
                    **e,
                }
                f.write(json.dumps(out, ensure_ascii=False) + "\n")

        _write_manifest(dest, github_login, team_id, sid, events, rel_path,
                        integrity, stats, header)
        imported += 1
        print(f"  [dsh] {sid[:28]:28s} {len(events):5d} events -> {rel_path}")

    print(f"[dsh] scanned {total} log(s) in workspace "
          f"({len(logs)} total, home={home}), imported {imported}, "
          f"already present {skipped}")
    return imported


if __name__ == "__main__":
    import argparse

    ap = argparse.ArgumentParser()
    ap.add_argument("--dest", required=True)
    ap.add_argument("--team-id", required=True)
    ap.add_argument("--github-login", required=True)
    ap.add_argument("--since")
    a = ap.parse_args()
    n = backfill(Path(a.dest), a.team_id, a.github_login, a.since)
    raise SystemExit(0 if n else 1)

